/* Sale Analytics – hành động, form, tự động hóa, xuất Excel, đồng bộ Google Sheets, vòng render. */
"use strict";
const TABS=[['overview','Tổng quan','M4 13h6V4H4zM14 20h6v-9h-6zM4 20h6v-4H4zM14 4v4h6V4z'],['orders','Đơn hàng','M6 3h12v18l-3-2-3 2-3-2-3 2zM9 8h6M9 12h6'],['debt','Công nợ','M3 7h18v10H3zM7 12h.01M12 9.5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5z'],['pipeline','Pipeline','M4 5h16l-6 7v6l-4 2v-8z'],['more','Menu','M4 7h16M4 12h16M4 17h16']];
function navOpen(){$('#app').classList.add('nav-open');document.body.style.overflow='hidden';const c=document.querySelector('#nav [aria-current]');if(c)c.scrollIntoView({block:'center'})}
function navClose(){const a=$('#app');if(a&&a.classList.contains('nav-open')){a.classList.remove('nav-open');document.body.style.overflow=''}}
function setFocus(on){document.documentElement.classList.toggle('focus',on);try{localStorage.setItem('sa.focus',on?'1':'')}catch(_){}const b=$('#focusBtn');if(b){b.setAttribute('aria-pressed',on);b.title=on?'Thoát chế độ tập trung (phím F)':'Chế độ tập trung (phím F)'}}
try{if(localStorage.getItem('sa.focus'))document.documentElement.classList.add('focus')}catch(_){}
// Giữ cỡ chữ trục biểu đồ ≥ ~9px khi biểu đồ bị thu nhỏ trong khung hẹp
function fitCharts(){document.querySelectorAll('#view svg.cc').forEach(s=>{const vb=s.viewBox.baseVal,w=s.getBoundingClientRect().width;if(!vb||!vb.width||!w)return;const sc=w/vb.width;s.style.setProperty('--tick',Math.max(10.5,Math.min(17,9.5/sc)).toFixed(1)+'px')})}
let rzT=0;window.addEventListener('resize',()=>{clearTimeout(rzT);rzT=setTimeout(fitCharts,120)});
function render(){
  build();const v=V[S.view]?S.view:'overview';
  const crit=M.checks.filter(c=>c.sev==='crit').length,openT=M.tasks.filter(t=>t.status!=='done').length,od=M.customers.filter(c=>c.maxOd>60).length;
  const cnt={automation:openT?`<span class="cnt${crit?' hot':''}">${openT}</span>`:'',debt:od?`<span class="cnt hot">${od}</span>`:'',pipeline:`<span class="cnt">${M.openOpps.length}</span>`,contracts:M.contracts.filter(c=>c.status==='Sắp hết hạn').length?`<span class="cnt">${M.contracts.filter(c=>c.status==='Sắp hết hạn').length}</span>`:'',product:M.stock.some(s=>s.status==='Sắp hết hàng')?'<span class="cnt hot">!</span>':''};
  $('#nav').innerHTML=GROUPS.map(([g,l])=>`<div class="ngrp">${l}</div>`+VIEWS.filter(x=>x[2]===g).map(([id,l])=>`<button data-act="go" data-v="${id}"${id===v?' aria-current="page"':''}><span>${l}</span>${cnt[id]||''}</button>`).join('')).join('');
  $('#vtitle').innerHTML=`<span class="crumb">${esc((GROUPS.find(g=>g[0]===VIEWS.find(x=>x[0]===v)[2])||[])[1]||'Sale Analytics')}</span>${esc(VIEWS.find(x=>x[0]===v)[1])}`;
  const tb=$('#tabbar');if(tb)tb.innerHTML=TABS.map(([id,l,ic])=>`<button data-act="${id==='more'?'navOpen':'go'}" data-v="${id}"${id===v||(id==='more'&&!TABS.some(t=>t[0]===v))?' aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${ic}"/></svg><span>${l}</span>${id!=='more'&&cnt[id]&&/hot/.test(cnt[id])?'<i class="tdot"></i>':''}</button>`).join('');
  const ae=document.activeElement,af=ae&&ae.dataset&&ae.dataset.f,aid=ae&&ae.id,sel=ae&&ae.selectionStart;const sy=window.scrollY;
  $('#view').innerHTML=V[v]();
  const el=af?document.querySelector(`#view [data-f="${af}"]`):aid?document.getElementById(aid):null;if(el&&el.tagName==='INPUT'){el.focus();try{if(sel!=null)el.setSelectionRange(sel,sel)}catch(_){}}
  window.scrollTo(0,sy);fitCharts();if(window.banner)banner();if(v==='contracts'&&S._prev)docPreview();
}
function go(v){navClose();if(!V[v])v='overview';S.view=v;S.f.page=0;S.pg={};if(location.hash!=='#'+v){try{history.replaceState(null,'','#'+v)}catch(_){location.hash=v}}render();window.scrollTo(0,0);if(window.onGo)onGo(v)}
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(V[v]&&v!==S.view){S.view=v;render()}});
const MODEL_F=['period','region','channel','team','commMonth'];
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset&&el.dataset.f){const k=el.dataset.f;S.f[k]=el.value;S.f.page=0;S.pg={};if(MODEL_F.includes(k))invalidate();if(k.startsWith('doc'))S._prev=false;render()}});
let qT=0;document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset&&el.dataset.f&&el.tagName==='INPUT'){clearTimeout(qT);qT=setTimeout(()=>{S.f[el.dataset.f]=el.value;S.f.page=0;S.pg={};render()},220)}});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b)return;const a=b.dataset.act;if(!ACT[a])return;if(b.tagName==='A'||b.tagName==='BUTTON')ev.preventDefault();if(b.disabled)return;ACT[a](b,ev)});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){closeDrawer();navClose()}const tg=ev.target,typing=tg&&(/INPUT|SELECT|TEXTAREA/.test(tg.tagName)||tg.isContentEditable);if(!typing&&!ev.metaKey&&!ev.ctrlKey&&!ev.altKey&&(ev.key==='f'||ev.key==='F')&&$('#drawerWrap').hidden){ev.preventDefault();setFocus(!document.documentElement.classList.contains('focus'))}if((ev.key==='Enter'||ev.key===' ')&&ev.target.getAttribute&&ev.target.getAttribute('role')==='button'){ev.preventDefault();ev.target.click()}});
function tick(){const n=new Date();const c=$('#clock');if(c)c.textContent=n.toLocaleDateString('vi-VN',{weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'})+' · '+n.toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'});
  if(G&&G.asOf!==iso(realToday())){invalidate();render();toast('Sang ngày mới: dữ liệu, tuổi nợ, thuế suất đã cập nhật đến '+vn(realToday()))}}

/* ---------- drawer chi tiết ---------- */
const dh=(t,s)=>`<div class="dh"><div><h2 style="font-size:20px">${t}</h2>${s?`<div class="small muted">${s}</div>`:''}</div><button class="btn sm" data-act="close">Đóng</button></div>`;
function custDrawer(id){const c=M.C[id];if(!c)return;const os=M.orders.filter(o=>o.cust===id);const ks=M.monthsAll.slice(-12);const v=ks.map(k=>sum(os.filter(o=>o.m===k),o=>o.net));
  const ct=M.contracts.filter(x=>x.cust===id),op=M.opps.filter(o=>o.cust===id&&!['won','lost'].includes(o.stage)),vs=M.visits.filter(x=>x.cust===id).slice(-5).reverse();
  openDrawer(dh(esc(c.name),`${c.id} · ${esc(c.type)} · ${CH_SHORT[c.ch]} · ${esc(c.province)} · ${tierPill(c.tier)} ${c.blocked?pill('Khóa giao hàng','crit'):''}`)+
  `<div class="kpis">${kpi('DT 12 tháng',fmtM(c.rev12))}${kpi('Công nợ',fmtM(c.ar),'Quá hạn '+fmtM(c.overdue))}${kpi('Hạn mức',fmtM(c.creditLimit),'Đã dùng '+pct(c.use,0))}${kpi('Lần mua cuối',c.last?vn(c.last):'—',c.recency<999?c.recency+' ngày trước':'')}</div>
  <div class="panel"><div class="kv small"><span>Phụ trách</span><b>${esc(repName(c.rep))}</b><span>Liên hệ</span><b>${esc(c.contact||'')} · ${esc(c.phone||'')}</b><span>MST</span><b>${esc(c.taxId||'')}</b><span>Địa chỉ</span><b>${esc(c.addr||'')}</b><span>Thời hạn thanh toán</span><b>${c.terms} ngày</b><span>Phân khúc RFM</span><b>${esc(c.seg||'—')} (R${c.r||'-'} F${c.f||'-'} M${c.mm||'-'})</b><span>Khách từ</span><b>${vn(c.since)}</b></div>${spark(v)}<span class="small muted"> 12 tháng</span></div>
  <div class="panel"><h3 style="font-size:15px">Hóa đơn còn nợ</h3>${tbl(['Hóa đơn','Ngày','Hạn',['Còn nợ'],'Tuổi nợ'],os.filter(o=>o.out>0).slice(-12).reverse().map(o=>`<tr><td class="mono small">${o.inv}</td><td>${vn(o.date)}</td><td>${vn(o.due)}</td>${tdn(fmt(o.out))}<td>${pill(o.bucket,o.od>60?'crit':o.od>0?'warn':'mute')}</td></tr>`))}</div>
  ${ct.length?`<div class="panel"><h3 style="font-size:15px">Hợp đồng</h3>${tbl(['Số','Loại','Hết hạn','Trạng thái'],ct.map(k=>`<tr><td class="small mono">${esc(k.id)}</td><td class="small">${esc(k.kind)}</td><td>${vn(k.end)}</td><td>${pill(k.status,k.status==='Đang hiệu lực'?'ok':'warn')}</td></tr>`))}</div>`:''}
  ${op.length?`<div class="panel"><h3 style="font-size:15px">Cơ hội đang mở</h3>${op.map(o=>`<div class="small">${o.id} · ${esc(o.name)} · ${fmtM(o.amount)} · ${STAGE[o.stage].l}</div>`).join('')}</div>`:''}
  ${vs.length?`<div class="panel"><h3 style="font-size:15px">Viếng thăm gần đây</h3>${vs.map(x=>`<div class="small">${vn(x.date)} ${esc(x.checkin)} · ${esc(repName(x.rep))} · ${esc(x.purpose)} · ${esc(x.status)}</div>`).join('')}</div>`:''}
  <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn pri" data-act="orderNew" data-c="${id}"${lock()}>Tạo đơn</button><button class="btn" data-act="payNew" data-c="${id}"${lock()}>Thu tiền</button><button class="btn" data-act="custEdit" data-id="${id}"${lock()}>Sửa thông tin & hạn mức</button><button class="btn" data-act="docFor" data-t="confirm" data-c="${id}">Biên bản xác nhận nợ</button><button class="btn" data-act="docFor" data-t="reminder" data-c="${id}">Thư nhắc nợ</button><button class="btn" data-act="docFor" data-t="quote" data-c="${id}">Báo giá</button></div>`)}
function repDrawer(id){const r=M.RP[id];if(!r)return;const st=M.repStats.find(x=>x.r.id===id)||{};const ks=M.monthsAll.slice(-12);const v=ks.map(k=>sum(M.orders.filter(o=>o.rep===id&&o.m===k),o=>o.net)),t=ks.map(k=>M.tgMonth(k,{rep:id}));
  const cs=M.customers.filter(c=>c.rep===id).sort((a,b)=>b.rev12-a.rev12);const cm=M.comm.find(c=>c.r.id===id);
  openDrawer(dh(esc(r.name),`${r.id} · ${esc(r.title)} · ${r.team?esc(TEAM[r.team].name):''} · vào làm ${vn(r.hire)}`)+`<div class="kpis">${kpi('Doanh thu kỳ',fmtM(st.rev),'Chỉ tiêu '+fmtM(st.tgt))}${kpi('% đạt',pct(st.ach,0),'Hạng '+(st.rank||'—'),achCls(st.ach||0)==='crit'?'crit':'')}${kpi('Công nợ phụ trách',fmtM(st.ar),'>90 ngày '+fmtM(st.od90))}${kpi('Hoa hồng tháng',fmtM(cm?cm.net:0),cm?cm.rate+'% · đạt '+pct(cm.ach,0):'')}</div>
  <div class="panel">${colChart(ks.map(monthName),[{n:'Doanh thu',c:'var(--c1)',values:v}],{h:200,line:{n:'Chỉ tiêu',c:'var(--c3)',values:t,dash:true}})}</div>
  <div class="panel"><h3 style="font-size:15px">Khách hàng phụ trách (${cs.length})</h3>${tbl(['Khách hàng',['DT 12 tháng'],['Công nợ'],'Trạng thái'],cs.slice(0,15).map(c=>`<tr><td>${cLink(c.id)}</td>${tdn(fmtM(c.rev12))}${tdn(fmtM(c.ar))}<td>${pill(c.status,c.status==='Đang hoạt động'?'ok':'warn')}</td></tr>`))}</div><p class="small muted">Email: ${esc(r.email)} · Lương cứng ${fmtM(r.base)} (liên thông HR Analytics để tính lương 3P + hoa hồng).</p>`)}
function orderDrawer(id){const o=M.orders.find(x=>x.id===id);if(!o)return;const[s,c]=ordStatus(o);
  openDrawer(dh('Đơn '+esc(o.id),`${vn(o.date)} · Hóa đơn ${CO.invoiceSerial} ${o.inv} · ${pill(s,c)}`)+`<div class="panel"><div class="kv small"><span>Khách hàng</span><b>${cLink(o.cust)}</b><span>Nhân viên</span><b>${esc(repName(o.rep))}</b><span>Kênh</span><b>${CHANNELS[o.ch]}</b><span>Hạn thanh toán</span><b>${vn(o.due)}</b></div></div>
  <div class="panel">${tbl(['Sản phẩm',['SL'],['Đơn giá'],['CK'],['Thành tiền']],o.lines.map(([sku,q,p,d])=>`<tr><td>${esc((PROD[sku]||{}).name||sku)}</td>${tdn(fmt(q))}${tdn(fmt(p))}${tdn(pct(d,0))}${tdn(fmt(q*p*(1-d)))}</tr>`),`<tr><td colspan="4">Tiền hàng${o.ret?' (đã trừ trả lại '+pct(o.ret,0)+')':''}</td>${tdn(fmt(o.net))}</tr><tr><td colspan="4">Thuế GTGT ${o.vatRate}%</td>${tdn(fmt(o.vat))}</tr><tr class="tot"><td colspan="4"><b>Tổng thanh toán</b></td>${tdn('<b>'+fmt(o.gross)+'</b>')}</tr>`)}</div>
  <div class="panel"><h3 style="font-size:15px">Thanh toán</h3>${o.pays.length?o.pays.map(p=>`<div class="small">${vn(p[0])} · ${fmt(p[1])} đ ${p[2]?'(phiếu thu)':''}</div>`).join(''):'<p class="small muted">Chưa thanh toán.</p>'}<p class="small">Còn nợ: <b>${fmt(o.out)}</b> đ${o.od>0?' · quá hạn '+o.od+' ngày · lãi chậm trả tạm tính '+fmt(o.out*P('lateInterest')/100*o.od/365)+' đ':''}</p></div>
  <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-act="docFor" data-t="po" data-c="${o.cust}">Xác nhận đơn</button><button class="btn" data-act="docFor" data-t="delivery" data-c="${o.cust}">Biên bản giao nhận</button>${o.out>0?`<button class="btn" data-act="payNew" data-c="${o.cust}"${lock()}>Thu tiền</button>`:''}${o.manual?`<button class="btn ghost" data-act="orderVoid" data-id="${o.id}"${lock()}>Hủy đơn nhập tay</button>`:''}</div>`)}
function oppDrawer(id){const o=M.opps.find(x=>x.id===id);if(!o)return;const open=!['won','lost'].includes(o.stage);
  openDrawer(dh(esc(o.id)+' · '+esc(o.name),`${esc(o.cust?custName(o.cust):o.prospect)} · ${esc(repName(o.rep))} · nguồn ${esc(o.source)}`)+`<div class="kpis">${kpi('Giá trị',fmtM(o.amount))}${kpi('Giai đoạn',STAGE[o.stage].l,o.p+'% · trọng số '+fmtM(o.w))}${kpi('Ngày chốt dự kiến',vn(o.expClose),o.overdue?'Đã quá ngày':'')}${kpi('Hoạt động cuối',vn(o.last),o.idle+' ngày trước',o.stale?'warn':'')}</div>
  ${open?`<div class="panel"><h3 style="font-size:15px">Cập nhật cơ hội</h3><div class="form"><label>Giai đoạn<select id="op_stage">${optHtml(STAGES.map(s=>[s[0],s[1]+' ('+s[2]+'%)']),o.stage)}</select></label><label>Giá trị (đ)<input id="op_amt" type="number" value="${Math.round(o.amount)}"></label><label>Ngày chốt dự kiến<input id="op_exp" type="date" value="${o.expClose}"></label><label>Lý do (nếu thua)<select id="op_loss"><option value=""></option>${optHtml(['Giá cao hơn đối thủ','Ngân sách khách hàng bị cắt','Giữ nhà cung cấp hiện tại','Không liên lạc được người quyết định','Sản phẩm chưa phù hợp quy cách','Thời gian giao hàng không đáp ứng'],'')}</select></label><label class="full">Ghi chú hoạt động<input id="op_note" placeholder="vd. Đã demo máy pha chế, chờ báo giá lần 2"></label></div><button class="btn pri" data-act="oppSave" data-id="${o.id}"${lock()} style="margin-top:8px">Lưu</button> <span class="small muted">Chuyển sang “Thắng” sẽ tạo hợp đồng chờ ký trong mô-đun Hợp đồng.</span></div>`:`<p>${o.stage==='won'?pill('Đã thắng '+vn(o.closed),'ok'):pill('Thua: '+(o.lossReason||''),'crit')}</p>`}${o.notes?`<div class="panel small">${esc(o.notes)}</div>`:''}`)}
function contractDrawer(id){const k=M.contracts.find(x=>x.id===id);if(!k)return;
  openDrawer(dh(esc(k.id),esc(k.kind)+' · '+esc(custName(k.cust)))+`<div class="kpis">${kpi('Giá trị',fmtM(k.value))}${kpi('Đã xuất hóa đơn',fmtM(k.invoiced),pct(k.progress,0))}${kpi('Còn phải thu',fmtM(k.out),'Quá hạn '+fmtM(k.overdue))}${kpi('Hiệu lực',vn(k.end),k.status)}</div><div class="panel small"><div class="kv"><span>Thời hạn thanh toán</span><b>${k.terms} ngày</b><span>Phạt vi phạm</span><b>${k.penalty}% (≤ 8% – Điều 301 LTM)</b><span>Phụ trách</span><b>${esc(repName(k.rep))}</b>${k.opp?`<span>Từ cơ hội</span><b>${k.opp}</b>`:''}</div></div>
  <div style="display:flex;gap:8px;flex-wrap:wrap">${k.status==='Chờ ký'?`<button class="btn pri" data-act="contractSign" data-id="${esc(k.id)}"${lock()}>Đánh dấu đã ký</button>`:''}<button class="btn" data-act="docFor" data-t="annex" data-c="${k.cust}" data-k="${esc(k.id)}">Phụ lục gia hạn</button><button class="btn" data-act="docFor" data-t="reconcile" data-c="${k.cust}" data-k="${esc(k.id)}">Đối chiếu công nợ</button><button class="btn" data-act="docFor" data-t="liquidation" data-c="${k.cust}" data-k="${esc(k.id)}">Thanh lý</button></div>`)}

/* ---------- form ---------- */
const custOpts=(filter,cur)=>optHtml(M.customers.filter(filter||(()=>true)).sort((a,b)=>a.name<b.name?-1:1).map(c=>[c.id,c.name+(c.blocked?' ⛔':'')]),cur);
const repOpts=(filter,cur)=>optHtml(M.reps.filter(r=>r.quota&&(!filter||filter(r))).map(r=>[r.id,r.name+' – '+TEAM[r.team].name]),cur);
function orderForm(cid){const c=M.C[cid]||M.customers[0];const skus=PRODUCTS.filter(p=>p.launch<=M.TS);
  openDrawer(dh('Tạo đơn hàng','Kiểm tra hạn mức, khóa giao hàng và trần khuyến mại '+P('promoCap')+'% trước khi lưu')+`<div class="panel"><div class="form"><label class="full">Khách hàng<select id="o_c">${custOpts(null,c.id)}</select></label><label>Ngày<input id="o_d" type="date" value="${M.TS}" max="${M.TS}"></label><label>Thời hạn TT (ngày)<input id="o_t" type="number" value="${c.terms}"></label></div>
  <table class="tbl"><thead><tr><th>Sản phẩm</th><th class="n">SL</th><th class="n">CK %</th></tr></thead><tbody>${[0,1,2,3].map(i=>`<tr><td><select id="o_s${i}"><option value=""></option>${optHtml(skus.map(p=>[p.id,p.name+' – '+fmt(p.price)+'đ/'+p.unit]),'')}</select></td><td><input id="o_q${i}" type="number" min="0" style="width:80px"></td><td><input id="o_k${i}" type="number" min="0" max="100" value="${c.ch==='GT'?(c.type==='Nhà phân phối'?12:8):c.ch==='MT'?16:c.ch==='KA'?6:10}" style="width:64px"></td></tr>`).join('')}</tbody></table>
  ${S.canAdmin?'<label class="chk"><input type="checkbox" id="o_ov"> Editor duyệt vượt hạn mức / khóa giao hàng (ghi nhật ký)</label>':''}<div id="o_msg" class="small"></div><button class="btn pri" data-act="orderSave" style="margin-top:8px">Lưu đơn & lập hóa đơn</button></div>`)}
function payForm(cid){const list=M.customers.filter(c=>c.ar>0);const c=M.C[cid]||list[0];
  openDrawer(dh('Phiếu thu tiền','Trừ vào hóa đơn cũ nhất (FIFO); tuổi nợ, hạn mức, hoa hồng cập nhật ngay')+`<div class="panel"><div class="form"><label class="full">Khách hàng<select id="p_c">${custOpts(x=>x.ar>0||x.id===cid,c&&c.id)}</select></label><label>Ngày thu<input id="p_d" type="date" value="${M.TS}" max="${M.TS}"></label><label>Số tiền (đ)<input id="p_a" type="number" min="0" value="${c?Math.round(c.overdue||c.ar):0}"></label><label>Hình thức<select id="p_m">${optHtml(['Chuyển khoản','Tiền mặt','Bù trừ công nợ','Thẻ / ví điện tử'],'Chuyển khoản')}</select></label><label class="full">Diễn giải<input id="p_n" placeholder="vd. Thu tiền HĐ tháng 10"></label></div><p class="small muted">Dư nợ hiện tại: <b>${c?fmt(c.ar):0}</b> đ, quá hạn ${c?fmt(c.overdue):0} đ. Thu tiền mặt từ ${fmtM(P('nonCash'))} cần chứng từ đầy đủ; bên mua không được khấu trừ thuế đầu vào nếu thanh toán tiền mặt (Luật GTGT 2024).</p><button class="btn pri" data-act="paySave">Lưu phiếu thu</button></div>`)}
function oppForm(){openDrawer(dh('Cơ hội mới')+`<div class="panel"><div class="form"><label class="full">Tên cơ hội<input id="n_name" placeholder="vd. Cung cấp siro cho chuỗi cà phê 12 điểm"></label><label>Khách hàng hiện hữu<select id="n_c"><option value="">— khách mới —</option>${custOpts(c=>['KA','MT'].includes(c.ch),'')}</select></label><label>Hoặc tên khách tiềm năng<input id="n_p"></label><label>Phụ trách<select id="n_r">${repOpts(r=>['KA','MT'].includes(r.ch),'')}</select></label><label>Giá trị (đ)<input id="n_a" type="number" value="500000000"></label><label>Ngày chốt dự kiến<input id="n_e" type="date" value="${iso(addDays(M.T,45))}"></label><label>Nguồn<select id="n_s">${optHtml(['Marketing inbound','Cold call','Giới thiệu','Hội chợ / sự kiện','Đối tác','Khách hàng hiện hữu'],'Cold call')}</select></label></div><button class="btn pri" data-act="oppCreate" style="margin-top:8px">Tạo cơ hội</button></div>`)}
