function exportXlsx(k){build();const sheets=k==='all'?Object.keys(XLB).flatMap(x=>XLB[x]()):XLB[k]();const meta=[['Sale Analytics – '+CO.short+' (dữ liệu mô phỏng)'],['Xuất lúc',new Date().toLocaleString('vi-VN')],['Bộ lọc',M.per.label+(S.f.region?' · '+REGIONS[S.f.region]:'')+(S.f.channel?' · '+CHANNELS[S.f.channel]:'')+(S.f.team?' · '+TEAM[S.f.team].name:'')],['Ghi chú','Ô công thức tự tính khi mở file; tuổi nợ dùng TODAY() nên cập nhật theo ngày mở.']];
  const bytes=xlsxBytes(sheets.concat([{name:'Thông tin',rows:meta}]));const t=(XL.find(x=>x[0]===k)||[,'Toan-bo'])[1];DL.save({filename:'Sale-Analytics_'+safeId(t.normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/gi,'d')).replace(/_+/g,'-')+'_'+M.TS+'.xlsx',data:bytes,mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});audit('export_xlsx',k)}
