 stockIn:()=>openDrawer(dh('Nhập kho')+`<div class="panel"><div class="form"><label class="full">Sản phẩm<select id="s_k">${optHtml(PRODUCTS.filter(p=>!p.service).map(p=>[p.id,p.name]),'')}</select></label><label>Số lượng (+ nhập / − điều chỉnh)<input id="s_q" type="number"></label><label>Ghi chú<input id="s_n" placeholder="Phiếu nhập kho số…"></label></div><button class="btn pri" data-act="stockSave" style="margin-top:8px">Lưu</button></div>`),
 stockSave:async()=>{const q=num('s_q');if(!q)return;await put('stock','NK'+uid(),{sku:val('s_k'),qty:q,note:val('s_n'),date:M.TS,by:S.meId||'demo'});closeDrawer();toast('Đã cập nhật tồn kho')},
