 docFor:b=>{S.f.docType=b.dataset.t;S.f.docCust=b.dataset.c;S.f.docRef=b.dataset.k||'';S._prev=true;closeDrawer();go('contracts');setTimeout(()=>{const e=document.getElementById('docPrev');if(e)e.scrollIntoView({behavior:'smooth'})},50)},
