 docOpen:b=>{const d=S.col.docs[b.dataset.id];if(!d)return;const h=d.html||buildDoc(d.type,d.cust,d.ref);openDrawer(dh(esc(DOC_TYPES[d.type]?DOC_TYPES[d.type].name:d.type),'Lập '+new Date(d.at).toLocaleString('vi-VN'))+`<div class="docwrap">${h}</div><button class="btn" data-act="docOpenPrint" data-id="${b.dataset.id}">In / PDF</button>`)},
